import numpy as np
import pandas as pd

def validate_bars(df):
    """A sorted list of problem codes; [] for clean bars."""
    problems = set()
    idx = df.index
    if (idx[1:] < idx[:-1]).any():
        problems.add("dates-not-rising")
    if idx.duplicated().any():
        problems.add("duplicate-date")
    if df["close"].isna().any():
        problems.add("nan-close")
    top = df[["open", "close"]].max(axis=1)
    bottom = df[["open", "close"]].min(axis=1)
    if (df["high"] < top).any():
        problems.add("high-below-body")
    if (df["low"] > bottom).any():
        problems.add("low-above-body")
    if (df["volume"] < 0).any():
        problems.add("negative-volume")
    days = idx.values.astype("datetime64[D]")
    if (np.busday_count(days[:-1], days[1:]) > 5).any():
        problems.add("gap")
    return sorted(problems)
